import 'package:fieldforce/features/wallet/provider/wallet_provider.dart';\nimport 'package:fieldforce/features/wallet/model/wallet_models.dart';\nimport 'package:fieldforce/theme/app_colours.dart';\nimport 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:material_symbols_icons/symbols.dart';\n\nclass AddBankAccountPage extends ConsumerStatefulWidget {\n  const AddBankAccountPage({super.key});\n\n  @override\n  ConsumerState<AddBankAccountPage> createState() => _AddBankAccountPageState();\n}\n\nclass _AddBankAccountPageState extends ConsumerState<AddBankAccountPage> {\n  final _formKey = GlobalKey<FormState>();\n  final _bankNameController = TextEditingController();\n  final _accountNumberController = TextEditingController();\n  final _accountHolderController = TextEditingController();\n  final _routingNumberController = TextEditingController();\n  final _swiftCodeController = TextEditingController();\n  \n  String _selectedAccountType = 'checking';\n  bool _isDefault = false;\n  bool _isLoading = false;\n\n  @override\n  void dispose() {\n    _bankNameController.dispose();\n    _accountNumberController.dispose();\n    _accountHolderController.dispose();\n    _routingNumberController.dispose();\n    _swiftCodeController.dispose();\n    super.dispose();\n  }\n\n  Future<void> _addBankAccount() async {\n    if (!_formKey.currentState!.validate()) {\n      return;\n    }\n\n    setState(() {\n      _isLoading = true;\n    });\n\n    try {\n      final bankAccount = BankAccountModel(\n        id: '', // Will be generated by backend\n        userId: '', // Will be set by backend\n        bankName: _bankNameController.text.trim(),\n        accountNumber: _accountNumberController.text.trim(),\n        accountHolderName: _accountHolderController.text.trim(),\n        routingNumber: _routingNumberController.text.trim(),\n        swiftCode: _swiftCodeController.text.trim(),\n        accountType: _selectedAccountType,\n        isDefault: _isDefault,\n        isVerified: false,\n        createdAt: DateTime.now(),\n        updatedAt: DateTime.now(),\n      );\n\n      await ref.read(walletControllerProvider.notifier).createBankAccount(bankAccount);\n\n      if (mounted) {\n        ScaffoldMessenger.of(context).showSnackBar(\n          const SnackBar(\n            content: Text('Bank account added successfully!'),\n            backgroundColor: Colors.green,\n          ),\n        );\n        Navigator.of(context).pop();\n      }\n    } catch (e) {\n      if (mounted) {\n        ScaffoldMessenger.of(context).showSnackBar(\n          SnackBar(\n            content: Text('Error adding bank account: $e'),\n            backgroundColor: Colors.red,\n          ),\n        );\n      }\n    } finally {\n      if (mounted) {\n        setState(() {\n          _isLoading = false;\n        });\n      }\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Colours.backgroundColor,\n      appBar: AppBar(\n        backgroundColor: Colours.backgroundColor,\n        elevation: 0,\n        title: const Text(\n          'Add Bank Account',\n          style: TextStyle(\n            color: Colours.whiteColor,\n            fontSize: 20,\n            fontWeight: FontWeight.w600,\n          ),\n        ),\n        leading: IconButton(\n          onPressed: () => Navigator.pop(context),\n          icon: const Icon(\n            Symbols.arrow_back,\n            color: Colours.whiteColor,\n          ),\n        ),\n      ),\n      body: Form(\n        key: _formKey,\n        child: SingleChildScrollView(\n          padding: const EdgeInsets.all(16.0),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              // Info Card\n              Container(\n                padding: const EdgeInsets.all(16),\n                decoration: BoxDecoration(\n                  color: kPrimary.withOpacity(0.1),\n                  borderRadius: BorderRadius.circular(12),\n                  border: Border.all(\n                    color: kPrimary.withOpacity(0.3),\n                  ),\n                ),\n                child: Row(\n                  children: [\n                    const Icon(\n                      Symbols.security,\n                      color: kPrimary,\n                      size: 24,\n                    ),\n                    const SizedBox(width: 12),\n                    Expanded(\n                      child: Text(\n                        'Your bank account information is encrypted and secure. We use bank-level security to protect your data.',\n                        style: TextStyle(\n                          color: Colours.whiteColor.withOpacity(0.9),\n                          fontSize: 14,\n                        ),\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n              \n              const SizedBox(height: 24),\n              \n              // Bank Name\n              TextFormField(\n                controller: _bankNameController,\n                style: const TextStyle(color: Colours.whiteColor),\n                decoration: InputDecoration(\n                  labelText: 'Bank Name *',\n                  labelStyle: TextStyle(\n                    color: Colours.whiteColor.withOpacity(0.7),\n                  ),\n                  prefixIcon: const Icon(\n                    Symbols.account_balance,\n                    color: kPrimary,\n                  ),\n                  border: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  enabledBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  focusedBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: const BorderSide(\n                      color: kPrimary,\n                      width: 2,\n                    ),\n                  ),\n                ),\n                validator: (value) {\n                  if (value == null || value.trim().isEmpty) {\n                    return 'Please enter bank name';\n                  }\n                  return null;\n                },\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // Account Holder Name\n              TextFormField(\n                controller: _accountHolderController,\n                style: const TextStyle(color: Colours.whiteColor),\n                decoration: InputDecoration(\n                  labelText: 'Account Holder Name *',\n                  labelStyle: TextStyle(\n                    color: Colours.whiteColor.withOpacity(0.7),\n                  ),\n                  prefixIcon: const Icon(\n                    Symbols.person,\n                    color: kPrimary,\n                  ),\n                  border: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  enabledBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  focusedBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: const BorderSide(\n                      color: kPrimary,\n                      width: 2,\n                    ),\n                  ),\n                ),\n                validator: (value) {\n                  if (value == null || value.trim().isEmpty) {\n                    return 'Please enter account holder name';\n                  }\n                  return null;\n                },\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // Account Number\n              TextFormField(\n                controller: _accountNumberController,\n                style: const TextStyle(color: Colours.whiteColor),\n                decoration: InputDecoration(\n                  labelText: 'Account Number *',\n                  labelStyle: TextStyle(\n                    color: Colours.whiteColor.withOpacity(0.7),\n                  ),\n                  prefixIcon: const Icon(\n                    Symbols.numbers,\n                    color: kPrimary,\n                  ),\n                  border: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  enabledBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  focusedBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: const BorderSide(\n                      color: kPrimary,\n                      width: 2,\n                    ),\n                  ),\n                ),\n                keyboardType: TextInputType.number,\n                validator: (value) {\n                  if (value == null || value.trim().isEmpty) {\n                    return 'Please enter account number';\n                  }\n                  if (value.length < 8) {\n                    return 'Account number must be at least 8 digits';\n                  }\n                  return null;\n                },\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // Account Type\n              DropdownButtonFormField<String>(\n                value: _selectedAccountType,\n                style: const TextStyle(color: Colours.whiteColor),\n                decoration: InputDecoration(\n                  labelText: 'Account Type',\n                  labelStyle: TextStyle(\n                    color: Colours.whiteColor.withOpacity(0.7),\n                  ),\n                  prefixIcon: const Icon(\n                    Symbols.account_balance_wallet,\n                    color: kPrimary,\n                  ),\n                  border: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  enabledBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  focusedBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: const BorderSide(\n                      color: kPrimary,\n                      width: 2,\n                    ),\n                  ),\n                ),\n                dropdownColor: Colours.cardColor,\n                items: [\n                  {'value': 'checking', 'label': 'Checking Account'},\n                  {'value': 'savings', 'label': 'Savings Account'},\n                  {'value': 'business', 'label': 'Business Account'},\n                ].map((Map<String, String> type) {\n                  return DropdownMenuItem<String>(\n                    value: type['value'],\n                    child: Text(\n                      type['label']!,\n                      style: const TextStyle(color: Colours.whiteColor),\n                    ),\n                  );\n                }).toList(),\n                onChanged: (String? newValue) {\n                  if (newValue != null) {\n                    setState(() {\n                      _selectedAccountType = newValue;\n                    });\n                  }\n                },\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // Routing Number\n              TextFormField(\n                controller: _routingNumberController,\n                style: const TextStyle(color: Colours.whiteColor),\n                decoration: InputDecoration(\n                  labelText: 'Routing Number (optional)',\n                  labelStyle: TextStyle(\n                    color: Colours.whiteColor.withOpacity(0.7),\n                  ),\n                  prefixIcon: const Icon(\n                    Symbols.route,\n                    color: kPrimary,\n                  ),\n                  border: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  enabledBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  focusedBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: const BorderSide(\n                      color: kPrimary,\n                      width: 2,\n                    ),\n                  ),\n                ),\n                keyboardType: TextInputType.number,\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // SWIFT Code\n              TextFormField(\n                controller: _swiftCodeController,\n                style: const TextStyle(color: Colours.whiteColor),\n                decoration: InputDecoration(\n                  labelText: 'SWIFT Code (optional)',\n                  labelStyle: TextStyle(\n                    color: Colours.whiteColor.withOpacity(0.7),\n                  ),\n                  prefixIcon: const Icon(\n                    Symbols.language,\n                    color: kPrimary,\n                  ),\n                  border: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  enabledBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: BorderSide(\n                      color: Colours.whiteColor.withOpacity(0.3),\n                    ),\n                  ),\n                  focusedBorder: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(12),\n                    borderSide: const BorderSide(\n                      color: kPrimary,\n                      width: 2,\n                    ),\n                  ),\n                ),\n              ),\n              \n              const SizedBox(height: 24),\n              \n              // Set as Default Switch\n              Container(\n                padding: const EdgeInsets.all(16),\n                decoration: BoxDecoration(\n                  color: Colours.cardColor,\n                  borderRadius: BorderRadius.circular(12),\n                ),\n                child: Row(\n                  children: [\n                    const Icon(\n                      Symbols.star,\n                      color: kPrimary,\n                    ),\n                    const SizedBox(width: 12),\n                    Expanded(\n                      child: Column(\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        children: [\n                          const Text(\n                            'Set as Default Account',\n                            style: TextStyle(\n                              color: Colours.whiteColor,\n                              fontSize: 16,\n                              fontWeight: FontWeight.w500,\n                            ),\n                          ),\n                          Text(\n                            'Use this account for withdrawals by default',\n                            style: TextStyle(\n                              color: Colours.whiteColor.withOpacity(0.7),\n                              fontSize: 12,\n                            ),\n                          ),\n                        ],\n                      ),\n                    ),\n                    Switch(\n                      value: _isDefault,\n                      onChanged: (value) {\n                        setState(() {\n                          _isDefault = value;\n                        });\n                      },\n                      activeColor: kPrimary,\n                    ),\n                  ],\n                ),\n              ),\n              \n              const SizedBox(height: 32),\n              \n              // Add Account Button\n              SizedBox(\n                width: double.infinity,\n                height: 50,\n                child: ElevatedButton(\n                  onPressed: _isLoading ? null : _addBankAccount,\n                  style: ElevatedButton.styleFrom(\n                    backgroundColor: kPrimary,\n                    shape: RoundedRectangleBorder(\n                      borderRadius: BorderRadius.circular(12),\n                    ),\n                  ),\n                  child: _isLoading\n                      ? const SizedBox(\n                          width: 20,\n                          height: 20,\n                          child: CircularProgressIndicator(\n                            strokeWidth: 2,\n                            valueColor: AlwaysStoppedAnimation<Color>(Colors.white),\n                          ),\n                        )\n                      : const Text(\n                          'Add Bank Account',\n                          style: TextStyle(\n                            color: Colors.white,\n                            fontSize: 16,\n                            fontWeight: FontWeight.w600,\n                          ),\n                        ),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n